∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (s : F.State), W.coding.canon (W.dmin s) = W.dmin s

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (s : F.State) (c : List W.Symbol),
  W.coding.decode c = some (Sum.inl (D0.Foundation.VerificationCore.representedState E s)) →
    D0.Foundation.VerificationCore.ShortlexLE (W.dmin s) c

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (s t : F.State) (l l' : E.protocol.Line),
  W.archiveCode (s, l) = W.archiveCode (t, l') ↔ F.profile s = F.profile t ∧ l = l'

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (s : F.State) (l l' : E.protocol.Line),
  l ≠ l' → W.archiveCode (s, l) ≠ W.archiveCode (s, l')

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (history : List (F.State × E.protocol.Line)) (n : ℕ),
  W.query (W.archive history) n = Option.map W.archiveCode history[n]?

∀ {F : D0.Foundation.EmpiricalTheoryFactorization.FutureExecution}
  {E : D0.Foundation.VerifiabilityNecessity.TheoryVerification F.futureEmpiricalTheory}
  (W : D0.Foundation.VerificationCore.SigmaWitness E) (history later : List (List W.Symbol)),
  ∀ n < history.length, W.query (history ++ later) n = W.query history n
